  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "In macaques, intravenous [11C]AZ10419369 showed rapid brain uptake with 3-4% of injected radioactivity in the brain, demonstrating meaningful CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Autoradiography in rats with AZD6370 showed no or low CNS levels of parent compound or metabolites, indicating insufficient blood-brain barrier penetration.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Sulfamide 28 in mice showed an exceptionally low brain/plasma exposure ratio and no brain ERK modulation, indicating poor CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-scoring transferred evidence is direct primate PET showing rapid and substantial brain uptake after intravenous administration, supporting meaningful CNS access. Several lower-scoring negative records from other molecules argue against CNS penetration, but the most direct and condition-matched evidence favors a pass.",
  "evidence_gaps": [
    "Mixed evidence includes multiple negative CNS-penetration records from other molecules, creating uncertainty in transfer.",
    "The top-scoring molecule also shows rodent efflux-substrate behavior, but this does not override direct primate/human PET evidence of meaningful brain uptake."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

